// AMERICA LOST THE SAME H-BOMB TWICE. Episode 9. Bright-model look: white-model dioramas on a painted blue sky (the
// collision at 31,000 ft, the village and its dust, the sea cutaway with the 24 March snap at night), glossy mannequins
// for every person (named on pills, never likenesses) and the 2D ledger graphics (counters, maps, quotes, documents).
// Narration is read straight from SCRIPT.md (numbered lines, incl. 20a/20b and 35a/35b); every line is voiced once
// (projects/palomares-vo, per-line ElevenLabs cache), so regrouping lines into shots reuses the audio.
// Facts: RESEARCH.md (§13 "Do not claim"). Per-line visual brief: VISUALS.md. 3D sets: SETS-3d.md (sets/pal-sets.js) and
// sets/clay-silver.js `figures`. Graphics: SETS-graphics.md. Cuts and their sounds: cuts.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { scoreTransitions } from './cuts.mjs';
import { voice } from '../palomares-vo/project.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const LINES = {}, ORDER = [];
for (const l of fs.readFileSync(path.join(here, 'SCRIPT.md'), 'utf8').split('\n')) { const m = l.match(/^(\d+[ab]?)\. (.*)$/); if (m) { LINES[m[1]] = m[2].trim(); ORDER.push(m[1]); } }
// L(a, b): script lines a..b in script order (a and b are numbers or '20a'-style ids), joined with '\n'
const L = (a, b = a) => { const i = ORDER.indexOf(String(a)), j = ORDER.indexOf(String(b));
  if (i < 0 || j < 0 || j < i) throw new Error(`SCRIPT line ${i < 0 ? a : b} missing`); return ORDER.slice(i, j + 1).map(k => LINES[k]).join('\n'); };

let n = 0;
const S = (set, vo, params = {}, extra = {}) => ({ id: `s${String(++n).padStart(3, '0')}`, set, vo, params, ...extra });
const CH = (num, title, sub, state, mood, more = {}) => ({ id: `ch${num}`, set: 'chapter', params: { num, title, sub, state, ...more }, min: 4.0, chapter: num, mood });
const MORAN = 'AS TOLD TO BARBARA MORAN', NYT = 'NYT REPORTED (2016)', ASOF = 'AS OF 21 OCT 2026', RECON = 'RECONSTRUCTION';
const MANN = 'MANNEQUIN · ILLUSTRATION', MORAN_SRC = 'SOURCE: B. MORAN, THE DAY WE LOST THE H-BOMB (2009)';
const NEVER = 999; // a cue that never fires inside the shot
// grid cells for the 'math found something' beat: the calculator's peak on the inshore debris field, Simó's point pale (rows N→S, 15 × 9, grid set geometry)
const MATH_CELLS = Array.from({ length: 9 }, (_, j) => Array.from({ length: 15 }, (_, i) => { const x = -9.8 + i * 1.5, z = -5.6 + j * 1.5, g = (dx, dz, s) => Math.exp(-(dx * dx + dz * dz) / (2 * s * s)); return +Math.min(1, 1.0 * g(x + 5.3, z + 2.2, 2.2) + 0.2 * g(x - 1.5, z - 5.0, 2.4) + 0.04).toFixed(2); }));
// mannequins (wardrobe, colour) for the recurring people
// Guest: a rear admiral in navy service dress (suit wardrobe, #3d5684; GUESTN is the lighter navy for night shots); Moody: suit_b (the overcoat shaded badly in close-ups)
const SIMO = { w: 'casual_a', c: 'cyan' }, GUEST = { w: 'suit', c: '#6a86b8' }, GUESTN = { w: 'suit', c: '#6a86b8' }, MOODY = { w: 'suit_b', c: 'white' };
const MCCAMIS = { w: 'office', c: 'white' }, SKAAR = { w: 'casual_b', c: 'red' }, MOONEY = { w: 'office', c: 'cyan' };

